import{_ as e,o as a,c as o,ag as s}from"./chunks/framework.qXLDknWC.js";const b=JSON.parse('{"title":"Section Tab Layout","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/section-layout.md","filePath":"configuration/section-layout.md"}'),i={name:"configuration/section-layout.md"};function n(r,t,l,c,h,d){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="section-tab-layout" tabindex="-1">Section Tab Layout <a class="header-anchor" href="#section-tab-layout" aria-label="Permalink to &quot;Section Tab Layout&quot;">​</a></h1><p>The workspace tab strip at the top of the character editor has <strong>18 section tabs</strong> by default — most of which you&#39;ll use regularly, but some you might never touch. The <strong>Sections</strong> tab in Settings lets you hide the tabs you don&#39;t need and reorder the rest however you like.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Your tab layout is stored locally in IndexedDB. It&#39;s not synced anywhere — it lives with the rest of your settings on this device.</p></div><h2 id="accessing-tab-layout-settings" tabindex="-1">Accessing Tab Layout Settings <a class="header-anchor" href="#accessing-tab-layout-settings" aria-label="Permalink to &quot;Accessing Tab Layout Settings&quot;">​</a></h2><ol><li>Open a character in the workspace.</li><li>Click <strong>Settings</strong> in the workspace header.</li><li>Click the <strong>Sections</strong> tab.</li><li>Make your changes, then click <strong>Save Settings</strong>.</li></ol><p>The tab strip updates as soon as you save. On mobile, the dropdown also reflects the new order and hides the same sections.</p><h2 id="showing-and-hiding-tabs" tabindex="-1">Showing and Hiding Tabs <a class="header-anchor" href="#showing-and-hiding-tabs" aria-label="Permalink to &quot;Showing and Hiding Tabs&quot;">​</a></h2><p>Each section is listed with its label and a short description. Click the <strong>👁 eye</strong> icon on the right to hide a tab.</p><p>Hidden sections move below a <strong>&quot;Hidden&quot;</strong> divider. To bring a tab back, click the <strong>👁‍🗨 eye-off</strong> icon next to it.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You can hide every tab if you really want to — the editor still works because the last-active section stays in place. You can always re-enable tabs from Settings.</p></div><h2 id="reordering-tabs" tabindex="-1">Reordering Tabs <a class="header-anchor" href="#reordering-tabs" aria-label="Permalink to &quot;Reordering Tabs&quot;">​</a></h2><p>Each visible tab has <strong>▲</strong> and <strong>▼</strong> arrow buttons on the left. Click them to move the tab up or down by one position.</p><p>The arrow buttons swap the tab with the <em>adjacent visible tab</em>, so you can move a tab right next to another one regardless of what&#39;s hidden in between.</p><p>Disabled arrow buttons (at 25% opacity) tell you when you&#39;re at the top or bottom of the visible list.</p><h2 id="reset-to-defaults" tabindex="-1">Reset to Defaults <a class="header-anchor" href="#reset-to-defaults" aria-label="Permalink to &quot;Reset to Defaults&quot;">​</a></h2><p>Click <strong>Reset to Defaults</strong> at the top of the tab to restore the original section order and show every section. This is a local change — it only takes effect after you click <strong>Save Settings</strong>.</p><h2 id="new-sections" tabindex="-1">New Sections <a class="header-anchor" href="#new-sections" aria-label="Permalink to &quot;New Sections&quot;">​</a></h2><p>When a new section type is added in a future update, it appears at the end of the visible list automatically. You don&#39;t need to manually enable it.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/CharacterVault/docs/configuration/ai-setup">AI Setup</a></li><li><a href="/CharacterVault/docs/features/editor">Text Editor</a></li><li><a href="/CharacterVault/docs/faq">FAQ</a></li></ul>',20)])])}const p=e(i,[["render",n]]);export{b as __pageData,p as default};
